<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
use WexaShelf\{Database,Repository,Installer,SystemHealth,SEOSettings};
if($argc!==2)throw new RuntimeException('Usage: php system-health.php PRIVATE_SYNTHETIC_DATABASE_JSON');
$config=json_decode(file_get_contents($argv[1]),true);if(!isset($config['database']))$config=['database'=>$config];$config['database']['name']='wexashelf_operations_080';$config['site']=['url'=>'http://localhost/operations','indexing'=>false];
$db=Database::connect($config);if($db->query('SHOW TABLES')->fetchAll())throw new RuntimeException('Dedicated operations schema must be empty.');Database::migrate($db);$repo=new Repository($db,$config);$storage=sys_get_temp_dir().'/wexa-operations-'.bin2hex(random_bytes(8));mkdir($storage,0700);$prior=getenv('WEXA_STORAGE_PATH');putenv('WEXA_STORAGE_PATH='.$storage);
function opsCheck(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
try{
 opsCheck(Installer::options([])['catalogMode']==='empty','Default is empty');foreach([['site_name'=>'<script>'],['site_name'=>str_repeat('x',81)],['catalog_mode'=>'arbitrary']]as$bad){try{Installer::options($bad);throw new RuntimeException('Invalid choice accepted');}catch(WexaShelf\ApiException){}}
 foreach(['empty','sample']as$mode){$db->beginTransaction();Installer::initializeCatalog($repo,$config,['siteName'=>'Synthetic English catalog','catalogMode'=>$mode],'en');$health=(new SystemHealth($db,$repo,$config))->state();opsCheck($health['installationMode']===$mode,'Mode persisted');opsCheck($mode==='empty'?$health['catalog']['records']===0:$health['catalog']['records']>0,'Catalog selection honored');opsCheck((new SEOSettings($repo,$config))->get()['siteName']==='Synthetic English catalog','Site identity saved');opsCheck($repo->setting('localization')['sourceLocale']==='en','New-content source English');if($mode==='sample')foreach($repo->allRecords()as$r)opsCheck(($r['sourceLocale']??'tr')==='tr','Sample source language preserved');opsCheck($health['productionVerified']===false&&$health['workers']['ai']===null,'No invented production or cron evidence');$encoded=json_encode($health);opsCheck(!str_contains($encoded,$config['database']['password'])&&!str_contains($encoded,$storage),'No credential/private path leak');$db->rollBack();}
 echo "PASS operations: empty/sample selection, identity validation, English default, preserved sample source language, bounded health and no invented production/cron evidence.\n";
}finally{if($db->inTransaction())$db->rollBack();$db->exec('SET FOREIGN_KEY_CHECKS=0');foreach($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN)as$table){if(!preg_match('/^ws_[a-z0-9_]+$/D',$table))throw new RuntimeException('Unexpected fixture table');$db->exec('DROP TABLE `'.$table.'`');}$db->exec('SET FOREIGN_KEY_CHECKS=1');rmdir($storage);putenv($prior===false?'WEXA_STORAGE_PATH':'WEXA_STORAGE_PATH='.$prior);}
